#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, M;
    cin >> n >> M;

    vector<vector<int>> divs(n + 1);
    for (int i = 2; i <= n; ++i) {
        for (int j = 2 * i; j <= n; j += i) {
            divs[j].push_back(i);
        }
    }

    vector<long long> F(n + 1, 0);
    F[1] = 1;
    if (n >= 2) F[2] = 2;

    for (int k = 3; k <= n; ++k) {
        F[k] = (2 * F[k - 1] + F[k / (k - 1)]) % M;
        long long sum_diff = 0;
        for (int d : divs[k]) {
            if (d >= 2 && d <= k - 2) {
                sum_diff += F[k / d] - F[(k - 1) / d];
            }
        }
        F[k] = (F[k] + sum_diff) % M;
    }

    cout << F[n] % M << "\n";

    return 0;
}
